    double distance = Math.sqrt(a.times(x).getDistanceSquared(b));
    assertEquals(0.0, distance, EPSILON);
    assertEquals(0.0, solver.getResidualNorm(), ConjugateGradientSolver.DEFAULT_MAX_ERROR);
