        fail("Should fail with power == 1");
    } catch (IllegalArgumentException e) {
        // expected
    }
    try {
        vec1.logNormalize(-1);
        fail("Should fail with negative power");
    } catch (IllegalArgumentException e) {
        // expected
    }
    try {
        vec2.logNormalize(Double.POSITIVE_INFINITY);
        fail("Should fail with positive infinity norm");
    } catch (IllegalArgumentException e) {
        // expected
    }
}

