    right.setQuick(0, 1);
    right.setQuick(1, 2);
    assertFalse(left.equals(right));
    assertFalse(left.hashCode() == right.hashCode());
    // Make sure that hash([1,0,2,0,0,0]) != hash([1,0,2])
