    Runnable initializer = new Runnable() {

        @Override
        public void run() {
            try {
                model.getNumUsers();
                initialized.setValue(true);
            } catch (TasteException te) {
                // oops
            }
        }
    };
    new Thread(initializer).start();
    // wait a second for thread to start and call getNumUsers()
