        assertEquals(mapNbTrees, capturedKeys.getValues().size());
        // check the returned keys
        for (TreeID k : capturedKeys.getValues()) {
            assertEquals(partition, k.partition());
            assertEquals(treeIndex, k.treeId());
            treeIndex++;
        }
    }
}

